package vn.edu.ltweb.jwtmvc; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class WebMvcTest{@Autowired MockMvc mvc; @Test void loginPageRenders()throws Exception{mvc.perform(get("/login")).andExpect(status().isOk()).andExpect(view().name("auth/login"));} @Test void profilePageRenders()throws Exception{mvc.perform(get("/profile")).andExpect(status().isOk()).andExpect(view().name("user/profile"));}}
